:scope .chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #333);
  background: var(--paper, #f9f9f9);
  padding: 2rem;
  line-height: 1.6;
  max-width: 1200px;
  margin: 0 auto;
}

:scope h1 {
  font-size: 2rem;
  color: var(--ink, #222);
  margin-bottom: 0.5rem;
  border-bottom: 2px solid var(--line, #ddd);
  padding-bottom: 0.5rem;
}

:scope .chapter-takeaway {
  font-size: 1.1rem;
  color: var(--muted, #666);
  margin-bottom: 2rem;
  font-style: italic;
}

:scope .workbench-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: start;
}

@media (max-width: 768px) {
  :scope .workbench-layout {
    grid-template-columns: 1fr;
  }
}

:scope .panel {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 8px;
  padding: 1.5rem;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

:scope h2 {
  font-size: 1.25rem;
  color: var(--accent, #0056b3);
  margin-top: 0;
  margin-bottom: 1rem;
}

:scope .panel-desc {
  font-size: 0.9rem;
  color: var(--muted, #666);
  margin-bottom: 1.5rem;
}

:scope .control-group {
  margin-bottom: 1.5rem;
}

:scope label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.5rem;
  font-size: 0.95rem;
}

:scope select {
  width: 100%;
  padding: 0.5rem;
  font-size: 1rem;
  border: 1px solid var(--line, #ccc);
  border-radius: 4px;
  background: #fff;
}

:scope .visualization-stage {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
  padding: 1rem;
  background: #f4f6f8;
  border-radius: 6px;
}

:scope .module-box {
  background: #fff;
  border: 1px solid var(--line, #ddd);
  border-radius: 6px;
  padding: 1rem;
  position: relative;
}

:scope .module-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted, #888);
  margin-bottom: 0.5rem;
  font-weight: 700;
}

:scope .status-indicator {
  display: inline-block;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-weight: 600;
  background: #eef;
  color: #33a;
  margin-bottom: 0.5rem;
  transition: all 0.3s ease;
}

:scope .status-indicator.collapsed {
  background: #fee;
  color: #a33;
}

:scope .doc-stream {
  display: flex;
  gap: 0.5rem;
}

:scope .doc-slot {
  width: 40px;
  height: 40px;
  background: #eee;
  border: 1px solid #ccc;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  color: #666;
  transition: all 0.3s ease;
}

:scope .doc-slot.active {
  background: var(--accent, #0056b3);
  color: #fff;
  border-color: var(--accent, #0056b3);
}

:scope .doc-slot.collapsed {
  background: #ccc;
  color: #888;
}

:scope .connection-arrow {
  height: 40px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

:scope .connection-arrow svg {
  width: 100%;
  height: 100%;
}

:scope .flow-path {
  transition: stroke 0.3s ease, stroke-dasharray 0.3s ease;
}

:scope .flow-head {
  transition: fill 0.3s ease;
}

:scope .flow-label {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.75rem;
  color: var(--muted, #666);
  background: rgba(255,255,255,0.8);
  padding: 0 0.25rem;
  white-space: nowrap;
}

:scope .attention-map {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  height: 30px;
  margin-top: 0.5rem;
}

:scope .attn-bar {
  flex: 1;
  background: var(--warm, #d97706);
  border-radius: 2px 2px 0 0;
  transition: height 0.3s ease, background 0.3s ease;
}

:scope .analysis-output {
  border-top: 1px solid var(--line, #eee);
  padding-top: 1rem;
}

:scope .analysis-output h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
  color: var(--ink, #333);
}

:scope .text-content {
  font-size: 0.95rem;
  color: var(--ink, #444);
  min-height: 3rem;
}

:scope .source-btn {
  background: transparent;
  border: 1px solid var(--line, #ccc);
  color: var(--muted, #666);
  padding: 0.25rem 0.5rem;
  font-size: 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  margin-top: 0.5rem;
  transition: all 0.2s;
}

:scope .source-btn:hover {
  background: var(--paper, #f0f0f0);
  color: var(--ink, #333);
}

:scope .bias-list {
  list-style: none;
  padding: 0;
  margin: 0 0 1.5rem 0;
}

:scope .bias-list li {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1rem;
  align-items: flex-start;
}

:scope .bias-icon {
  font-size: 1.2rem;
  flex-shrink: 0;
}

:scope .bias-text {
  font-size: 0.95rem;
  color: var(--ink, #444);
}

:scope .source-ref {
  font-size: 0.8rem;
  color: var(--muted, #888);
  margin-left: 0.5rem;
  font-style: italic;
}

:scope .data-table-container {
  margin-top: 2rem;
}

:scope .simple-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  margin-bottom: 0.5rem;
}

:scope .simple-table th,
:scope .simple-table td {
  border: 1px solid var(--line, #ddd);
  padding: 0.5rem;
  text-align: left;
}

:scope .simple-table th {
  background: #f4f6f8;
  font-weight: 600;
}

:scope .table-note {
  font-size: 0.8rem;
  color: var(--muted, #888);
  margin: 0;
}

:scope .chapter-footer {
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line, #ddd);
}

:scope .limitations-summary h3 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
  color: var(--ink, #333);
}

:scope .limitations-summary p {
  font-size: 0.95rem;
  color: var(--muted, #666);
  margin: 0;
}

javascript:
(function() {
  'use strict';

  // 安全访问全局数据
  const pmData = window.paperMindData || { tables: [], sources: {} };

  // 查找 Table 7 数据
  let table7Data = null;
  if (pmData.tables && Array.isArray(pmData.tables)) {
    table7Data = pmData.tables.find(t => t.id === 'p19-Table_7');
  }

  // DOM 元素引用
  const taskSelector = document.getElementById('task-selector');
  const retrieverStatus = document.getElementById('retriever-status');
  const generatorStatus = document.getElementById('generator-status');
  const docSlots = document.querySelectorAll('.doc-slot');
  const flowPath = document.querySelector('.flow-path');
  const flowHead = document.querySelector('.flow-head');
  const flowLabel = document.getElementById('flow-label');
  const attnBars = document.querySelectorAll('.attn-bar');
  const analysisText = document.getElementById('analysis-text');
  const tableBody = document.getElementById('dataset-table-body');

  // 状态常量
  const STATE_QA = {
    retrieverText: '活跃检索',
    retrieverClass: '',
    generatorText: '融合检索',
    generatorClass: '',
    flowColor: 'var(--accent, #0056b3)',
    flowDash: 'none',
    flowLabel: '检索内容参与生成（示意）',
    docActive: [0, 1, 2], // 模拟不同文档被激活
    attnHeights: ['40%', '70%', '50%'],
    attnColor: 'var(--warm, #d97706)',
    analysis: '在<strong>高事实需求</strong>任务 (如 Open-Domain QA) 中，检索器根据输入查询动态检索不同文档。生成器有效利用检索到的上下文，梯度信号能够反向传播至检索器，维持系统的端到端优化。',
    sourceId: 'S336' // 指向 Retrieval Collapse 段落，说明正常情况
  };

  const STATE_STORY = {
    retrieverText: '已坍缩',
    retrieverClass: 'collapsed',
    generatorText: '忽略检索 (退化 BART)',
    generatorClass: 'collapsed',
    flowColor: '#ccc',
    flowDash: '5, 5',
    flowLabel: '检索未被有效利用（示意）',
    docActive: [0], // 只检索同一个文档
    attnHeights: ['10%', '10%', '10%'], // 注意力均匀且低，表示忽略
    attnColor: '#ccc',
    analysis: '在<strong>低事实需求</strong>任务 (如故事生成) 中，检索组件发生“坍缩”：无论输入如何，始终检索相同文档。生成器学会忽略这些无用信息，导致 RAG 模型表现等同于未使用检索的 BART 模型。',
    sourceId: 'S336' // 指向 Retrieval Collapse 段落
  };

  // 更新可视化状态
  function updateVisualization(state) {
    // 更新文本状态
    retrieverStatus.textContent = state.retrieverText;
    retrieverStatus.className = 'status-indicator ' + (state.retrieverClass || '');

    generatorStatus.textContent = state.generatorText;
    generatorStatus.className = 'status-indicator ' + (state.generatorClass || '');

    // 更新流箭头
    flowPath.style.stroke = state.flowColor;
    flowPath.style.strokeDasharray = state.flowDash;
    flowHead.style.fill = state.flowColor;
    flowLabel.textContent = state.flowLabel;

    // 更新文档槽
    docSlots.forEach((slot, idx) => {
      slot.classList.remove('active', 'collapsed');
      if (state.docActive.includes(idx)) {
        slot.classList.add('active');
      } else {
        slot.classList.add('collapsed');
      }
    });

    // 更新注意力条
    attnBars.forEach((bar, idx) => {
      bar.style.height = state.attnHeights[idx] || '10%';
      bar.style.background = state.attnColor;
    });

    // 更新分析文本
    analysisText.innerHTML = state.analysis;

    // 更新来源按钮
    const existingBtn = analysisText.nextElementSibling;
    if (existingBtn && existingBtn.classList.contains('source-btn')) {
      existingBtn.setAttribute('data-source', state.sourceId);
    }
  }

  // 填充表格数据
  function renderTable() {
    if (!tableBody || !table7Data) return;

    tableBody.innerHTML = '';
    // 仅展示前 5 行作为示例，避免过长
    const rowsToShow = table7Data.rows;

    rowsToShow.forEach(row => {
      const tr = document.createElement('tr');
      const taskName = row.values['Task'];
      const trainCount = row.values['Train'];
      const testCount = row.values['Test'];

      tr.innerHTML = `
        <td>${taskName}</td>
        <td>${trainCount}</td>
        <td>${testCount}</td>
      `;
      tableBody.appendChild(tr);
    });
  }

  // 事件监听
  if (taskSelector) {
    taskSelector.addEventListener('change', function(e) {
      const taskType = e.target.value;
      if (taskType === 'qa') {
        updateVisualization(STATE_QA);
      } else if (taskType === 'story') {
        updateVisualization(STATE_STORY);
      }
    });
  }

  // 初始化
  renderTable();
  updateVisualization(STATE_QA);

})();
